class Widget {
public:
  // Templated constructor - can be instantiated with any type.
  template<typename T>
  Widget(const T& rhs) {}

  // Templated assignment operator.
  template<typename T>
  Widget& operator=(const T& rhs) { return *this; }

  // EVEN WITH the templates above, the compiler will still generate:
  // - A copy constructor: Widget(const Widget&)
  // - A move constructor: Widget(Widget&&)
  // - And their assignment operator counterparts.
};

void test() {
  Widget w1;
  Widget w2 = w1; // Calls the COMPILER-GENERATED copy constructor,
                  // NOT the templated constructor where T=Widget.
}
